#include <iostream>
#include <vector>
#include <array>
#include <algorithm>
#include <string>
#include <stack>
using namespace std;
#include <queue>
#include <functional>
#include <fstream>
#include <iomanip>
#include <utility>
struct Node{int key;Node* left;Node* right;}; void walk(Node*p){if(!p)return; cout<<p->key<<' '; walk(p->left); walk(p->right);}
int main(){ int n; cin>>n;
Node l{1,nullptr,nullptr},r{3,nullptr,nullptr},root{2,&l,&r}; Node* p=n==1?&root:nullptr; walk(p); cout<<"| "; stack<Node*> st; while(p||!st.empty()){while(p){st.push(p);p=p->left;} p=st.top();st.pop();cout<<p->key<<' ';p=p->right;} cout<<'\n';
}

