#include <array>
#include <algorithm>
#include <string>
#include <stack>
using namespace std;
#include <queue>
#include <functional>
#include <fstream>
#include <iomanip>
#include <utility>

int main(){ int n; cin>>n;
vector<vector<int>> adj=n==1?vector<vector<int>>{{1},{0},{},{}}:vector<vector<int>>{{1},{0,2},{1,3},{2}};vector<bool> seen(4);int components=0;for(int start=0;start<4;++start){if(seen[start])continue;++components;queue<int> q;q.push(start);seen[start]=true;while(!q.empty()){int u=q.front();q.pop();for(int v:adj[u])if(!seen[v]){seen[v]=true;q.push(v);}}}cout<<components<<'\n';
}

#include <iostream>
