#include <string>
#include <stack>
using namespace std;
#include <queue>
#include <functional>
#include <fstream>
#include <iomanip>
#include <utility>

int main(){ int n; cin>>n;
const int INF=100000;int w[3][3]={{INF,n==1?2:0,9},{INF,INF,3},{INF,INF,INF}};array<int,3>d{0,INF,INF};array<bool,3> used{};for(int k=0;k<3;++k){int u=-1;for(int v=0;v<3;++v)if(!used[v]&&(u==-1||d[v]<d[u]))u=v;if(u==-1||d[u]==INF)break;used[u]=true;for(int v=0;v<3;++v)if(w[u][v]!=INF)d[v]=min(d[v],w[u][v]);}cout<<d[2]<<'\n';
}

