#include <iostream>
#include <vector>
#include <array>
#include <algorithm>
#include <string>
#include <stack>
using namespace std;
#include <queue>
#include <functional>
#include <fstream>
#include <iomanip>
#include <utility>

int main(){ int n; cin>>n;
vector<vector<int>> adj=n==1?vector<vector<int>>{{1},{2},{0}}:vector<vector<int>>{{1},{2},{}};array<int,3> degree{};for(auto row:adj)for(int v:row)++degree[v];queue<int>q;for(int v=0;v<3;++v)if(degree[v]==0)q.push(v);int count=0;while(!q.empty()){int u=q.front();q.pop();++count;for(int v:adj[u])if(--degree[v]==0)q.push(v);}cout<<"dag "<<count<<'\n';
}

